/**
 * The office spatial contract: office-layout-v01.json, generated by the office authoring
 * scripts (kept with the source assets, outside this repository) and shared with the Blender build.
 *
 * Frame (metres): Y up, X to the right, Z toward the entrance. A yaw turns an object's local
 * +Z ("front") to (sin yaw, cos yaw) in the ground plane; an Openling with yaw 0 faces the
 * entrance. Node names in the office GLBs equal the item ids here.
 */
import raw from "./office-layout-v01.json";

export type Vec2 = [number, number];
export type Vec3 = [number, number, number];

export type ZoneId = "lobby" | "command" | "workers" | "research" | "devtest" | "reporting" | "ops" | "break";

export interface OfficeZone {
  id: ZoneId;
  number: number;
  label: string;
  tagline: string;
  polygon: Vec2[];
  center: Vec2;
  bounds: [number, number, number, number];
}

export interface OfficeWall {
  id: string;
  kind: "solid" | "partition" | "glass" | "low";
  from: Vec2;
  to: Vec2;
  height: number;
  thickness: number;
  zone: ZoneId | null;
  openings: [number, number, string][];
}

export interface OfficeItem {
  id: string;
  type: string;
  zone: ZoneId;
  position: Vec3;
  yaw: number;
  collection?: "dynamic";
  params: Record<string, unknown> & {
    seatPose?: Vec3;
    seatYaw?: number;
    restPose?: Vec3;
    restYaw?: number;
  };
}

export type AnchorKind = "stand" | "sit" | "approach" | "work" | "camera";

export interface OfficeAnchor {
  id: string;
  zone: ZoneId;
  position: Vec3;
  yaw: number;
  kind: AnchorKind;
  clip?: string;
  /** Where the Openling stands before the final interaction move into this anchor. */
  approach?: Vec3;
  /** Item ids the approach may brush (its own seat). */
  ignore?: string[];
  /** Dynamic seat item that rolls under the Openling. */
  chair?: string;
  desk?: string;
  seat?: string;
  alias?: string;
  seatHeight?: number;
  camera?: ZoneId;
}

export type Obstacle =
  | { id: string; kind: "circle"; center: Vec2; radius: number; source: string }
  | { id: string; kind: "box"; center: Vec2; size: Vec2; yaw: number; source: string }
  | { id: string; kind: "segment"; a: Vec2; b: Vec2; halfWidth: number; source: string };

export interface OfficeCamera {
  id: string;
  label: string;
  position: Vec3;
  target: Vec3;
  fov: number;
  zone?: ZoneId;
}

export interface OfficeLight {
  id: string;
  type: "directional" | "hemisphere" | "spot" | "point";
  position?: Vec3;
  target?: Vec3;
  color?: string;
  sky?: string;
  ground?: string;
  intensity: number;
  castShadow?: boolean;
  angle?: number;
  penumbra?: number;
  distance?: number;
}

export interface OfficeSign {
  id: string;
  text: string;
  sub?: string;
  style: string;
  logo?: boolean;
  smile?: boolean;
}

export interface OfficeLayout {
  version: string;
  units: string;
  character: {
    height: number; width: number; depth: number; radius: number; propRadius: number; seatHeight: number; deskHeight: number;
    deskReach: number; deskEdge: number; seatBack: number; walkSpeed: number; eyeHeight: number;
  };
  clearance: number;
  architecture: {
    wallThickness: number;
    heights: Record<string, number>;
    outline: Vec2[];
    porch: [number, number, number, number];
    bounds: [number, number, number, number];
  };
  zones: OfficeZone[];
  walls: OfficeWall[];
  items: OfficeItem[];
  anchors: OfficeAnchor[];
  nav: { waypoints: { id: string; position: Vec3; zone: ZoneId | null }[]; edges: [string, string, number][]; links: [string, string][] };
  obstacles: Obstacle[];
  cameras: OfficeCamera[];
  lights: OfficeLight[];
  signs: OfficeSign[];
}

export const OFFICE_LAYOUT = raw as unknown as OfficeLayout;

/** Asset URLs of the three office GLBs (exported by the Blender build in the same frame). */
export const OFFICE_GLB_URLS = [
  "/models/openlings/office/office-shell-v01.glb",
  "/models/openlings/office/office-furniture-v01.glb",
  "/models/openlings/office/office-decor-v01.glb",
] as const;

export class LayoutIndex {
  readonly layout: OfficeLayout;
  private readonly anchors = new Map<string, OfficeAnchor>();
  private readonly items = new Map<string, OfficeItem>();
  private readonly zones = new Map<ZoneId, OfficeZone>();

  constructor(layout: OfficeLayout = OFFICE_LAYOUT) {
    this.layout = layout;
    for (const a of layout.anchors) this.anchors.set(a.id, a);
    for (const i of layout.items) this.items.set(i.id, i);
    for (const z of layout.zones) this.zones.set(z.id, z);
  }

  anchor(id: string): OfficeAnchor {
    const a = this.anchors.get(id);
    if (!a) throw new Error(`Unknown office anchor: ${id}`);
    return a;
  }

  hasAnchor(id: string): boolean {
    return this.anchors.has(id);
  }

  item(id: string): OfficeItem {
    const i = this.items.get(id);
    if (!i) throw new Error(`Unknown office item: ${id}`);
    return i;
  }

  zone(id: ZoneId): OfficeZone {
    return this.zones.get(id)!;
  }

  /** The anchor an alias (e.g. Research_Work) stands for. */
  resolve(id: string): OfficeAnchor {
    const a = this.anchor(id);
    return a.alias ? this.anchor(a.alias) : a;
  }

  /** Zone that contains a ground point (by polygon), or null in the corridors. */
  zoneAt(x: number, z: number): ZoneId | null {
    for (const zone of this.layout.zones) if (pointInPolygon(x, z, zone.polygon)) return zone.id;
    return null;
  }

  camera(id: string): OfficeCamera | undefined {
    return this.layout.cameras.find((c) => c.id === id);
  }
}

export function pointInPolygon(x: number, z: number, poly: Vec2[]): boolean {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [xi, zi] = poly[i];
    const [xj, zj] = poly[j];
    if ((zi > z) !== (zj > z) && x < ((xj - xi) * (z - zi)) / (zj - zi) + xi) inside = !inside;
  }
  return inside;
}

export function yawDir(yaw: number): Vec2 {
  return [Math.sin(yaw), Math.cos(yaw)];
}

/** Shortest signed angle from a to b. */
export function angleDelta(a: number, b: number): number {
  let d = (b - a) % (Math.PI * 2);
  if (d > Math.PI) d -= Math.PI * 2;
  if (d < -Math.PI) d += Math.PI * 2;
  return d;
}

/** Yaw that faces from (x0, z0) toward (x1, z1). */
export function yawTo(x0: number, z0: number, x1: number, z1: number): number {
  return Math.atan2(x1 - x0, z1 - z0);
}
